-- 338_analytics_destinations.sql
/* Storelib analytics sent on to a store's other tools, and read by them (round ana-1029): new `analytics_destinations`, one row per store and tool (Google Analytics 4 by the Measurement Protocol, Meta's Conversions API, PostHog, or a signed webhook of the store's own), holding the tool's ids (`config`: a measurement id, a pixel id, a host) and its API secret, access token, project key or webhook address and signing secret sealed by the server (`secret_ciphertext`, AES-256-GCM, never readable by a browser); new `analytics_forward_jobs`, the queue and the delivery log: one row per tool and event (`event_key`, unique per tool, so a purchase told twice is sent once), the event's facts (`facts`, no person in them), what consent allowed about the person (`person`, emptied once the row is done), its state (queued, sending, sent, failed, skipped), the tries and when the next one is due, the tool's answer code and its error; new `analytics_api_tokens`, read only keys for GET /api/v1/analytics, kept as a SHA-256 of the key and its first characters (the key itself is shown once), revocable (`revoked_at`). Written and read only by the server (lib/analytics/destinations): row level security on, nothing granted to anon or authenticated. New tables only; no existing row changes. Until it runs, Analytics › Send to says this part is needed and nothing is sent. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.analytics_destinations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL CHECK (provider IN ('ga4', 'meta', 'posthog', 'webhook')), status text NOT NULL DEFAULT 'connected' CHECK (status IN ('connected', 'paused')), account_label text CHECK (account_label IS NULL OR length(account_label) <= 200), config jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(config) = 'object'), secret_ciphertext text CHECK (secret_ciphertext IS NULL OR secret_ciphertext LIKE 'v1.%'), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT analytics_destinations_one_per_tool UNIQUE (creator_id, provider));
CREATE INDEX IF NOT EXISTS analytics_destinations_connected_idx ON public.analytics_destinations (creator_id) WHERE status = 'connected';
ALTER TABLE public.analytics_destinations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.analytics_destinations FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.analytics_destinations TO service_role;
CREATE TABLE IF NOT EXISTS public.analytics_forward_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), destination_id uuid NOT NULL REFERENCES public.analytics_destinations(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, event_name text NOT NULL CHECK (event_name IN ('page_view', 'view_item', 'purchase', 'refund', 'lead', 'sign_up', 'test')), event_key text NOT NULL CHECK (length(event_key) BETWEEN 1 AND 200), subject_ref text CHECK (subject_ref IS NULL OR length(subject_ref) <= 100), facts jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(facts) = 'object'), person jsonb CHECK (person IS NULL OR jsonb_typeof(person) = 'object'), status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'sending', 'sent', 'failed', 'skipped')), attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0), next_attempt_at timestamptz NOT NULL DEFAULT now(), locked_until timestamptz, response_status integer, last_error text CHECK (last_error IS NULL OR length(last_error) <= 500), sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT analytics_forward_jobs_once UNIQUE (destination_id, event_key));
CREATE INDEX IF NOT EXISTS analytics_forward_jobs_due_idx ON public.analytics_forward_jobs (next_attempt_at) WHERE status IN ('queued', 'sending');
CREATE INDEX IF NOT EXISTS analytics_forward_jobs_log_idx ON public.analytics_forward_jobs (destination_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS analytics_forward_jobs_ref_idx ON public.analytics_forward_jobs (creator_id, subject_ref) WHERE status = 'queued';
ALTER TABLE public.analytics_forward_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.analytics_forward_jobs FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.analytics_forward_jobs TO service_role;
CREATE TABLE IF NOT EXISTS public.analytics_api_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, name text NOT NULL CHECK (length(name) BETWEEN 1 AND 80), token_hash text NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'), token_prefix text NOT NULL CHECK (length(token_prefix) <= 20), created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz, revoked_at timestamptz);
CREATE INDEX IF NOT EXISTS analytics_api_tokens_creator_idx ON public.analytics_api_tokens (creator_id, created_at DESC);
ALTER TABLE public.analytics_api_tokens ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.analytics_api_tokens FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.analytics_api_tokens TO service_role;
notify pgrst, 'reload schema';

-- 341_connected_email_platforms.sql
/* Connected email platforms and the store's own sending domain (Emails > Platforms, run after 166). Brevo, MailerLite and Kit join Klaviyo and Omnisend on the marketing sync: the commerce_integrations provider check and the marketing_sync_items provider check are rebuilt with every value they already allow plus brevo, mailerlite and kit (read from the database, so a part that added its own keeps them; a check that is already a pattern, part 163, is left as it is). email_sending_domains keeps one domain per store, added to Storelib's Mailgun account: its SPF, DKIM, tracking and DMARC records with what the last check found, pending until Mailgun says it is active, then verified and used as From on campaigns, automations and the emails buyers get. A domain belongs to one store only. Server only (the service role); nobody reads it with a browser key. No rows change. Safe to run again. */
DO $do$ DECLARE v text[]; BEGIN IF to_regclass('public.commerce_integrations') IS NULL THEN RAISE NOTICE 'commerce_integrations is not there yet: run part 78 first'; RETURN; END IF; IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.commerce_integrations'::regclass AND conname = 'commerce_integrations_provider_check' AND pg_get_constraintdef(oid) LIKE '%~%') THEN RAISE NOTICE 'commerce_integrations_provider_check is a pattern (part 163), which already lets every name in: left as it is'; RETURN; END IF; SELECT coalesce(array_agg(DISTINCT m[1]), '{}'::text[]) INTO v FROM pg_constraint c CROSS JOIN LATERAL regexp_matches(pg_get_constraintdef(c.oid), '[''{,]([a-z][a-z0-9_]*)(?=['',}])', 'g') AS m WHERE c.conrelid = 'public.commerce_integrations'::regclass AND c.conname = 'commerce_integrations_provider_check'; v := ARRAY(SELECT DISTINCT x FROM unnest(v || ARRAY['manual', 'supplier_email', 'custom_webhook', 'csv', 'printful', 'printify', 'gelato', 'cj_dropshipping', 'shipstation', 'shippo', 'easypost', 'klaviyo', 'omnisend', 'brevo', 'mailerlite', 'kit']) AS x ORDER BY x); ALTER TABLE public.commerce_integrations DROP CONSTRAINT IF EXISTS commerce_integrations_provider_check; EXECUTE format('ALTER TABLE public.commerce_integrations ADD CONSTRAINT commerce_integrations_provider_check CHECK (provider = ANY (%L::text[])) NOT VALID', v); END $do$;
DO $do$ DECLARE v text[]; BEGIN IF to_regclass('public.marketing_sync_items') IS NULL THEN RAISE NOTICE 'marketing_sync_items is not there yet: run part 166 first'; RETURN; END IF; SELECT coalesce(array_agg(DISTINCT m[1]), '{}'::text[]) INTO v FROM pg_constraint c CROSS JOIN LATERAL regexp_matches(pg_get_constraintdef(c.oid), '[''{,]([a-z][a-z0-9_]*)(?=['',}])', 'g') AS m WHERE c.conrelid = 'public.marketing_sync_items'::regclass AND c.conname = 'marketing_sync_items_provider_check'; v := ARRAY(SELECT DISTINCT x FROM unnest(v || ARRAY['klaviyo', 'omnisend', 'brevo', 'mailerlite', 'kit']) AS x ORDER BY x); ALTER TABLE public.marketing_sync_items DROP CONSTRAINT IF EXISTS marketing_sync_items_provider_check; EXECUTE format('ALTER TABLE public.marketing_sync_items ADD CONSTRAINT marketing_sync_items_provider_check CHECK (provider = ANY (%L::text[])) NOT VALID', v); END $do$;
CREATE TABLE IF NOT EXISTS public.email_sending_domains (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL UNIQUE REFERENCES public.creators(id) ON DELETE CASCADE, domain text NOT NULL CHECK (char_length(domain) BETWEEN 4 AND 253 AND domain = lower(domain) AND domain ~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$'), from_local text NOT NULL DEFAULT 'hello' CHECK (from_local ~ '^[a-z0-9]([a-z0-9._+-]{0,62}[a-z0-9])?$'), provider text NOT NULL DEFAULT 'mailgun' CHECK (provider IN ('mailgun')), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'verified', 'failed')), records jsonb NOT NULL DEFAULT '[]'::jsonb, last_checked_at timestamptz, verified_at timestamptz, last_error text CHECK (last_error IS NULL OR char_length(last_error) <= 500), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS email_sending_domains_domain_key ON public.email_sending_domains (domain);
ALTER TABLE public.email_sending_domains ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.email_sending_domains FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.email_sending_domains TO service_role;
notify pgrst, 'reload schema';

-- 342_seo_index_status.sql
/* SEO status in /admin/seo (round 44). seo_index_status keeps one row per address Storelib's sitemaps list: its kind, the sitemap file it came from, the Search Console property it belongs to (none for a creator's own domain), whether it is in the sitemap now, Google's answer from the URL Inspection API (verdict, coverage, indexing, robots.txt, fetch, last crawl, Google's canonical and the page's own, when it was asked) and the page's SEO score with each check that made it. seo_inspection_quota counts the inspections spent per property, per Pacific day and per minute, and seo_take_inspection_quota takes from it in one locked step so two runs cannot both spend the last of it. seo_sync_state is where the cron is in its walk through the sitemap files. seo_index_totals adds up each kind for the console. Service role only. No rows change. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.seo_index_status (url text PRIMARY KEY CHECK (char_length(url) BETWEEN 8 AND 2048 AND url ~ '^https?://'), kind text NOT NULL CHECK (kind IN ('page', 'blog', 'help', 'legal', 'profile', 'product', 'collection', 'onepage', 'community', 'website')), source text NOT NULL CHECK (char_length(source) BETWEEN 1 AND 200), property text CHECK (property IS NULL OR char_length(property) BETWEEN 3 AND 300), in_sitemap boolean NOT NULL DEFAULT true, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), left_sitemap_at timestamptz, google_status text CHECK (google_status IN ('indexed', 'not_indexed', 'unknown', 'error', 'no_property')), verdict text, coverage_state text, indexing_state text, robots_txt_state text, page_fetch_state text, last_crawl_time timestamptz, google_canonical text, user_canonical text, inspection_link text, inspect_error text, inspected_at timestamptz, score smallint CHECK (score IS NULL OR score BETWEEN 0 AND 100), checks jsonb, http_status smallint, score_error text, scored_at timestamptz, expanded_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS seo_index_status_kind_idx ON public.seo_index_status (kind, url);
CREATE INDEX IF NOT EXISTS seo_index_status_source_idx ON public.seo_index_status (source) WHERE in_sitemap;
CREATE INDEX IF NOT EXISTS seo_index_status_inspect_next_idx ON public.seo_index_status (property, inspected_at ASC NULLS FIRST, url) WHERE in_sitemap AND property IS NOT NULL;
CREATE INDEX IF NOT EXISTS seo_index_status_score_next_idx ON public.seo_index_status (scored_at ASC NULLS FIRST, url) WHERE in_sitemap;
CREATE INDEX IF NOT EXISTS seo_index_status_google_idx ON public.seo_index_status (google_status, url);
CREATE INDEX IF NOT EXISTS seo_index_status_expand_idx ON public.seo_index_status (expanded_at ASC NULLS FIRST, url) WHERE in_sitemap AND source LIKE 'websites-%';
DO $do$ DECLARE sch text; BEGIN SELECT n.nspname INTO sch FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'pg_trgm'; IF sch IS NULL AND EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_trgm') THEN IF to_regnamespace('extensions') IS NOT NULL THEN CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA extensions; sch := 'extensions'; ELSE CREATE EXTENSION IF NOT EXISTS pg_trgm; SELECT n.nspname INTO sch FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'pg_trgm'; END IF; END IF; IF sch IS NULL THEN RAISE NOTICE 'pg_trgm is not available: searching addresses in /admin/seo works, without an index'; RETURN; END IF; EXECUTE format('CREATE INDEX IF NOT EXISTS seo_index_status_url_trgm_idx ON public.seo_index_status USING gin (url %I.gin_trgm_ops)', sch); END $do$;
ALTER TABLE public.seo_index_status ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.seo_index_status FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.seo_index_status TO service_role;
CREATE TABLE IF NOT EXISTS public.seo_inspection_quota (property text NOT NULL CHECK (char_length(property) BETWEEN 3 AND 300), window_kind text NOT NULL CHECK (window_kind IN ('day', 'minute')), window_start timestamptz NOT NULL, used integer NOT NULL DEFAULT 0 CHECK (used >= 0), PRIMARY KEY (property, window_kind, window_start));
ALTER TABLE public.seo_inspection_quota ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.seo_inspection_quota FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.seo_inspection_quota TO service_role;
CREATE TABLE IF NOT EXISTS public.seo_sync_state (id smallint PRIMARY KEY DEFAULT 1 CHECK (id = 1), files text[] NOT NULL DEFAULT '{}', next_file integer NOT NULL DEFAULT 0 CHECK (next_file >= 0), sweep_started_at timestamptz, sweep_finished_at timestamptz, last_run_at timestamptz, last_error text, updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.seo_sync_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.seo_sync_state FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.seo_sync_state TO service_role;
CREATE OR REPLACE FUNCTION public.seo_take_inspection_quota(p_property text, p_want integer, p_per_day integer, p_per_minute integer) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE d timestamptz := date_trunc('day', now() AT TIME ZONE 'America/Los_Angeles') AT TIME ZONE 'America/Los_Angeles'; m timestamptz := date_trunc('minute', now()); used_d integer; used_m integer; n integer; BEGIN IF p_property IS NULL OR coalesce(p_want, 0) <= 0 THEN RETURN 0; END IF; INSERT INTO public.seo_inspection_quota (property, window_kind, window_start, used) VALUES (p_property, 'day', d, 0), (p_property, 'minute', m, 0) ON CONFLICT DO NOTHING; SELECT used INTO used_d FROM public.seo_inspection_quota WHERE property = p_property AND window_kind = 'day' AND window_start = d FOR UPDATE; SELECT used INTO used_m FROM public.seo_inspection_quota WHERE property = p_property AND window_kind = 'minute' AND window_start = m FOR UPDATE; n := greatest(0, least(p_want, p_per_day - used_d, p_per_minute - used_m)); IF n > 0 THEN UPDATE public.seo_inspection_quota SET used = used + n WHERE property = p_property AND ((window_kind = 'day' AND window_start = d) OR (window_kind = 'minute' AND window_start = m)); END IF; DELETE FROM public.seo_inspection_quota WHERE window_start < now() - interval '3 days'; RETURN n; END $f$;
REVOKE ALL ON FUNCTION public.seo_take_inspection_quota(text, integer, integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.seo_take_inspection_quota(text, integer, integer, integer) TO service_role;
CREATE OR REPLACE FUNCTION public.seo_index_totals() RETURNS TABLE (kind text, listed bigint, in_sitemap bigint, answers_200 bigint, indexed bigint, not_indexed bigint, not_checked bigint, no_property bigint, scored bigint, average_score numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT s.kind, count(*), count(*) FILTER (WHERE s.in_sitemap), count(*) FILTER (WHERE s.in_sitemap AND s.http_status = 200), count(*) FILTER (WHERE s.in_sitemap AND s.google_status = 'indexed'), count(*) FILTER (WHERE s.in_sitemap AND s.google_status = 'not_indexed'), count(*) FILTER (WHERE s.in_sitemap AND s.property IS NOT NULL AND (s.google_status IS NULL OR s.google_status IN ('unknown', 'error'))), count(*) FILTER (WHERE s.in_sitemap AND s.property IS NULL), count(s.score) FILTER (WHERE s.in_sitemap), round(avg(s.score) FILTER (WHERE s.in_sitemap), 1) FROM public.seo_index_status s GROUP BY s.kind ORDER BY s.kind $f$;
REVOKE ALL ON FUNCTION public.seo_index_totals() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.seo_index_totals() TO service_role;
notify pgrst, 'reload schema';

-- 343_sitemap_indexes.sql
/* Sitemap indexes (round 44): the reads storelib.com's sitemap files make by id, one slice of the id space at a time, a thousand rows after the last id seen (lib/seo/sitemaps.ts readKeyset), and the counts its index makes. Four partial indexes, nothing else: products by id where published (the products files and their count), products by creator and id where published (each creator's product count in the creators files), store_theme_installs by id where published (the websites files and their count), communities by id where published and not deleted (the communities files). With them a file of ten thousand pages is a seek and a short walk at five million rows as at five thousand. A missing table or column is skipped with a notice. No row changes. LOCKS: a plain CREATE INDEX stops writes to its table while it builds, held until the paste ends, so on a large products table run supabase/sql/RUN_SITEMAP_INDEXES_CONCURRENTLY.sql first, one line per Run, or with psql -f; this part then finds each index made and takes no lock. Until it runs the sitemaps read the same rows, more slowly. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 343: products_sitemap_idx skipped, public.products does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'status') THEN RAISE NOTICE 'part 343: products_sitemap_idx skipped, public.products lacks a column it needs'; RETURN; END IF; IF to_regclass('public.products_sitemap_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS products_sitemap_idx ON public.products (id) WHERE status = 'published'; END $do$;
DO $do$ BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 343: products_sitemap_creator_idx skipped, public.products does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'status') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'creator_id') THEN RAISE NOTICE 'part 343: products_sitemap_creator_idx skipped, public.products lacks a column it needs'; RETURN; END IF; IF to_regclass('public.products_sitemap_creator_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS products_sitemap_creator_idx ON public.products (creator_id, id) WHERE status = 'published'; END $do$;
DO $do$ BEGIN IF to_regclass('public.store_theme_installs') IS NULL THEN RAISE NOTICE 'part 343: store_theme_installs_sitemap_idx skipped, public.store_theme_installs does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'store_theme_installs' AND column_name = 'status') THEN RAISE NOTICE 'part 343: store_theme_installs_sitemap_idx skipped, public.store_theme_installs lacks a column it needs'; RETURN; END IF; IF to_regclass('public.store_theme_installs_sitemap_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS store_theme_installs_sitemap_idx ON public.store_theme_installs (id) WHERE status = 'published'; END $do$;
DO $do$ BEGIN IF to_regclass('public.communities') IS NULL THEN RAISE NOTICE 'part 343: communities_sitemap_idx skipped, public.communities does not exist here (part 81)'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'communities' AND column_name = 'status') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'communities' AND column_name = 'deleted_at') THEN RAISE NOTICE 'part 343: communities_sitemap_idx skipped, public.communities lacks a column it needs'; RETURN; END IF; IF to_regclass('public.communities_sitemap_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS communities_sitemap_idx ON public.communities (id) WHERE status = 'published' AND deleted_at IS NULL; END $do$;
notify pgrst, 'reload schema';

-- check: every column true
select (to_regclass('public.store_credit_notes') is not null and coalesce((select c.relrowsecurity from pg_class c where c.oid = to_regclass('public.store_credit_notes')), false) and to_regprocedure('public.storelib_credit_note(uuid, uuid, text, integer, text, jsonb)') is not null and not has_function_privilege('anon', 'public.storelib_credit_note(uuid, uuid, text, integer, text, jsonb)', 'EXECUTE') and not has_function_privilege('authenticated', 'public.storelib_credit_note(uuid, uuid, text, integer, text, jsonb)', 'EXECUTE') and not has_table_privilege('anon', 'public.store_credit_notes', 'SELECT') and not has_table_privilege('authenticated', 'public.store_credit_notes', 'SELECT')) as p329_store_credit_notes, (exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'analytics_events' and column_name = 'link_label') and exists (select 1 from pg_constraint where conname = 'analytics_events_event_type_check' and pg_get_constraintdef(oid) like '%nav_click%') and to_regprocedure('public.analytics_nav_clicks(uuid,text,uuid,uuid,timestamptz,timestamptz,timestamptz,timestamptz)') is not null and to_regprocedure('public.analytics_row_series(uuid,text,uuid,uuid,uuid,timestamptz,timestamptz,timestamptz[],text)') is not null) as p331_analytics_clicks_rows, (exists (select 1 from pg_constraint where conname = 'store_team_members_permissions_check' and pg_get_constraintdef(oid) like '%billing_manage%')) as p333_team_money_areas, (not exists (select 1 from (values ('commerce_order_events', 'commerce_order_events_creator_kind_idx'), ('email_flow_sends', 'email_flow_sends_creator_status_idx'), ('onepages', 'onepages_creator_idx'), ('onepages', 'onepages_seller_idx'), ('community_messages', 'community_messages_community_created_idx'), ('community_direct_messages', 'community_direct_messages_community_created_idx'), ('community_chat_group_messages', 'community_chat_group_messages_community_created_idx'), ('community_messages', 'community_messages_reply_idx'), ('community_direct_messages', 'community_direct_messages_reply_idx'), ('community_chat_group_messages', 'community_chat_group_messages_reply_idx'), ('campaign_recipients', 'campaign_recipients_subscriber_idx'), ('email_recipients', 'email_recipients_subscriber_idx'), ('community_notifications', 'community_notifications_community_idx'), ('community_space_reads', 'community_space_reads_space_idx'), ('checkout_starts', 'checkout_starts_product_idx'), ('community_members', 'community_members_source_product_idx'), ('course_enrollments', 'course_enrollments_product_idx'), ('review_requests', 'review_requests_product_idx'), ('seller_notifications', 'seller_notifications_order_idx'), ('inventory_reservations', 'inventory_reservations_variant_idx'), ('product_channel_listings', 'product_channel_listings_product_idx')) as v(t, i) where to_regclass('public.' || v.t) is not null and to_regclass('public.' || v.i) is null) and (to_regprocedure('public.increment_product_sales(uuid)') is null or not has_function_privilege('anon', 'public.increment_product_sales(uuid)', 'EXECUTE')) and (to_regprocedure('public.upsert_customer(uuid, text, text, text, text, text, integer)') is null or not has_function_privilege('anon', 'public.upsert_customer(uuid, text, text, text, text, text, integer)', 'EXECUTE')) and (to_regprocedure('public.get_email_stats(uuid, timestamp with time zone, timestamp with time zone)') is null or not has_function_privilege('anon', 'public.get_email_stats(uuid, timestamp with time zone, timestamp with time zone)', 'EXECUTE')) and (to_regprocedure('public.refresh_daily_rollup(date)') is null or not has_function_privilege('anon', 'public.refresh_daily_rollup(date)', 'EXECUTE')) and (to_regprocedure('public.migrate_to_partitioned_analytics()') is null or not has_function_privilege('anon', 'public.migrate_to_partitioned_analytics()', 'EXECUTE')) and (to_regprocedure('public.initialize_creator_themes(uuid)') is null or not has_function_privilege('anon', 'public.initialize_creator_themes(uuid)', 'EXECUTE')) and not exists (select 1 from pg_policies where schemaname = 'public' and (tablename, policyname) in (('customers', 'System can manage customers'), ('verification_codes', 'Allow all verification code operations'), ('security_events', 'Allow all security event operations'), ('seller_notifications', 'Service role can insert notifications'))) and not exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relname in ('analytics_events_partitioned', 'onepage_views_partitioned') and not c.relrowsecurity) and (to_regclass('public.storefront_indexability') is null or not has_table_privilege('anon', 'public.storefront_indexability', 'SELECT')) and (to_regclass('public.digital_assets') is null or not has_column_privilege('anon', 'public.digital_assets', 'file_path', 'SELECT'))) as p334_database_load_and_isolation, (to_regclass('public.analytics_destinations') is not null and to_regclass('public.analytics_forward_jobs') is not null and to_regclass('public.analytics_api_tokens') is not null and exists (select 1 from pg_constraint where conname = 'analytics_forward_jobs_once')) as p338_analytics_destinations, (to_regclass('public.email_sending_domains') is not null and exists (select 1 from pg_constraint where conname = 'marketing_sync_items_provider_check' and pg_get_constraintdef(oid) like '%mailerlite%') and (exists (select 1 from pg_constraint where conname = 'commerce_integrations_provider_check' and (pg_get_constraintdef(oid) like '%mailerlite%' or pg_get_constraintdef(oid) like '%~%')))) as p341_connected_email_platforms, (case when to_regclass('public.seo_index_status') is null or to_regclass('public.seo_inspection_quota') is null or to_regclass('public.seo_sync_state') is null or to_regprocedure('public.seo_take_inspection_quota(text, integer, integer, integer)') is null or to_regprocedure('public.seo_index_totals()') is null then false else coalesce((select relrowsecurity from pg_class where oid = to_regclass('public.seo_index_status')), false) and not has_table_privilege('anon', 'public.seo_index_status', 'SELECT') and not has_function_privilege('anon', 'public.seo_take_inspection_quota(text, integer, integer, integer)', 'EXECUTE') end) as p342_seo_index_status, (to_regclass('public.products_sitemap_idx') is not null and to_regclass('public.products_sitemap_creator_idx') is not null and to_regclass('public.store_theme_installs_sitemap_idx') is not null and (to_regclass('public.communities') is null or to_regclass('public.communities_sitemap_idx') is not null)) as p343_sitemap_indexes;
